/**
 * Open-source licence data (generated by `bun run licenses` into licenses.generated.json).
 * The JSON is about 1 MB, so it is only required the first time the licences page opens.
 */
export interface LicenseInfo {
  name: string;
  version: string;
  license: string;
  author?: string;
  repository?: string;
  licenseText?: string;
}

export interface LicenseData {
  packages: LicenseInfo[];
  native: LicenseInfo[];
}

let cache: LicenseData | null = null;

export function getLicenseData(): LicenseData {
  if (!cache) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const raw = require('./licenses.generated.json') as Partial<LicenseData>;
    cache = { packages: raw.packages ?? [], native: raw.native ?? [] };
  }
  return cache;
}

/** Stable id for routes: "native:SQLCipher" or "npm:expo@54.0.29". */
export function licenseId(entry: LicenseInfo, kind: 'native' | 'npm'): string {
  return kind === 'native' ? `native:${entry.name}` : `npm:${entry.name}@${entry.version}`;
}

export function findLicense(data: LicenseData, id: string): LicenseInfo | undefined {
  if (id.startsWith('native:')) return data.native.find((e) => `native:${e.name}` === id);
  return data.packages.find((e) => `npm:${e.name}@${e.version}` === id);
}

/** Case-insensitive match on name, licence or author; every word of the query must match. */
export function filterLicenses(entries: LicenseInfo[], query: string): LicenseInfo[] {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return entries;
  return entries.filter((e) => {
    const hay = `${e.name} ${e.license} ${e.author ?? ''}`.toLowerCase();
    return words.every((w) => hay.includes(w));
  });
}
